from google.cloud import storage
import os

def get_storage_client():
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set")
    return storage.Client(project=project_id)

from google.cloud import translate_v3 as translate
import os

def stored_text_translate(payload: dict) -> dict:
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set")

    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [payload["text"]],
            "mime_type": "text/plain",  # Mime types: "text/plain", "text/html"
            "source_language_code": payload.get("source_language", "auto"),
            "target_language_code": payload["target_language"],
        }
    )

    translated_texts = [translation.translated_text for translation in response.translations]
    return {"translated_text": " ".join(translated_texts)}

import os
import google.generativeai as genai

def stored_asset_summary(payload: dict) -> dict:
    api_key = os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY environment variable not set")
    genai.configure(api_key=api_key)

    model = genai.GenerativeModel('gemini-pro')
    prompt = f"Summarize the following text:\n\n{payload['text']}"

    response = model.generate_content(prompt)

    # The response might have multiple parts or candidates. We'll take the first one.
    if response.candidates and response.candidates[0].content and response.candidates[0].content.parts:
        summary_text = " ".join([part.text for part in response.candidates[0].content.parts])
        return {"summary": summary_text}
    else:
        return {"summary": "Could not generate summary."}

import os
import google.generativeai as genai

def asset_metadata_embedding(payload: dict) -> dict:
    api_key = os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY environment variable not set")
    genai.configure(api_key=api_key)

    model = genai.GenerativeModel('text-embedding-004')

    # The text to embed can be a combination of metadata and extracted text.
    text_to_embed = payload["text"]

    response = model.embed_content(model="models/text-embedding-004", content=text_to_embed)

    if response.embedding and response.embedding.values:
        return {"embedding": response.embedding.values}
    else:
        return {"embedding": []}
